// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DAO} from "../src/DAO.sol";

contract InvMutTest is Test {
    DAO c;
    function setUp() public { c = new DAO(); }
    function testFuzz_property(address addrA, address addrB, string memory typeA, string memory typeB) public {
        vm.assume(addrA != address(0) && addrB != address(0));
        vm.assume(addrA != addrB);
        vm.assume(bytes(typeA).length > 0 && bytes(typeB).length > 0);
        vm.assume(keccak256(bytes(typeA)) != keccak256(bytes(typeB)));
        c.init(address(0x1), address(0x2), address(0x3));
        vm.prank(address(0x1111));
        c.newAddressProposal(addrA, typeA);
        vm.prank(address(0x2222));
        c.newAddressProposal(addrB, typeB);
        assertTrue(c.mapPID_address(1) == addrA && c.mapPID_address(2) == addrB);
    }
}
